-- Module 11 (Phase 7F-0): clone provenance, frozen period times, and the data-model foundation of the per-year draft cap.
--
-- Purely additive: three nullable columns on "timetable_versions", two nullable columns on "timetable_generation_runs", one index,
-- one self foreign key, three CHECK constraints and one trigger. No table is created or dropped, no existing column or row is
-- altered (every existing row gets NULLs, which all the new constraints accept), and "timetable_entries" is untouched.
--
-- Part 1 is generated by `prisma migrate diff`. Part 2 is hand-written: Prisma's schema language cannot express CHECK constraints
-- or triggers (as in the earlier migrations).

-- ===== Part 1: generated =====

-- AlterTable
ALTER TABLE "timetable_generation_runs" ADD COLUMN     "periodTimes" JSONB,
ADD COLUMN     "periodTimesCapturedAt" TIMESTAMPTZ(3);

-- AlterTable
ALTER TABLE "timetable_versions" ADD COLUMN     "clonedFromId" TEXT,
ADD COLUMN     "periodTimes" JSONB,
ADD COLUMN     "periodTimesCapturedAt" TIMESTAMPTZ(3);

-- CreateIndex
CREATE INDEX "timetable_versions_clonedFromId_idx" ON "timetable_versions"("clonedFromId");

-- AddForeignKey
ALTER TABLE "timetable_versions" ADD CONSTRAINT "timetable_versions_clonedFromId_fkey" FOREIGN KEY ("clonedFromId") REFERENCES "timetable_versions"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- ===== Part 2: hand-written constraints =====

-- Period times and their capture time are both set or both null, and the times are a JSON array (the application validates the shape).
ALTER TABLE "timetable_versions"
  ADD CONSTRAINT "timetable_versions_period_times_check" CHECK (
    ("periodTimes" IS NULL AND "periodTimesCapturedAt" IS NULL)
 OR ("periodTimes" IS NOT NULL AND "periodTimesCapturedAt" IS NOT NULL AND jsonb_typeof("periodTimes") = 'array')
  );

ALTER TABLE "timetable_generation_runs"
  ADD CONSTRAINT "timetable_generation_runs_period_times_check" CHECK (
    ("periodTimes" IS NULL AND "periodTimesCapturedAt" IS NULL)
 OR ("periodTimes" IS NOT NULL AND "periodTimesCapturedAt" IS NOT NULL AND jsonb_typeof("periodTimes") = 'array')
  );

-- A version is never its own clone source.
ALTER TABLE "timetable_versions"
  ADD CONSTRAINT "timetable_versions_cloned_from_not_self_check" CHECK ("clonedFromId" IS NULL OR "clonedFromId" <> "id");

-- Provenance never crosses an academic year or a school: the source of a clone belongs to the same year and school as the clone.
-- Fires on insert and whenever clonedFromId is set or changed. The foreign key's ON DELETE SET NULL update fires it too, with NULL,
-- which it accepts. (The source is not locked here: a source deleted concurrently is handled by the foreign key itself.)
CREATE FUNCTION "timetable_versions_check_clone_provenance"() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  source_year   text;
  source_school text;
BEGIN
  IF NEW."clonedFromId" IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT "academicYearId", "schoolId" INTO source_year, source_school FROM "timetable_versions" WHERE "id" = NEW."clonedFromId";
  IF NOT FOUND THEN
    RETURN NEW; -- the foreign key reports a missing source
  END IF;
  IF source_year <> NEW."academicYearId" OR source_school <> NEW."schoolId" THEN
    RAISE EXCEPTION 'timetable version % cannot be cloned from a version of another academic year or school', NEW."id"
      USING ERRCODE = '23514', CONSTRAINT = 'timetable_versions_clone_provenance';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "timetable_versions_clone_provenance_trigger"
  BEFORE INSERT OR UPDATE OF "clonedFromId" ON "timetable_versions"
  FOR EACH ROW EXECUTE FUNCTION "timetable_versions_check_clone_provenance"();
